def edge(a, b, c): return (c[0] - a[0]) * (b[1] - a[1]) - (c[1] - a[1]) * (b[0] - a[0])

def test_raster(w, h):
    print(f"--- {w}x{h} ---")
    shift_y = (h - w * 0.5) / 2.0
    v0 = (w / 2.0, shift_y)
    v1 = (0.0, shift_y + w * 0.5)
    v2 = (w, shift_y + w * 0.5)
    for y in range(h):
        row = []
        for x in range(w):
            py = int(y / 2) * 2 + 0.5
            px = x + 0.5
            w0 = edge(v1, v2, (px, py))
            w1 = edge(v2, v0, (px, py))
            w2 = edge(v0, v1, (px, py))
            if w0 >= 0 and w1 >= 0 and w2 >= 0: row.append('@')
        if row: print(f"{y:2}: {len(row)} chars")

test_raster(20, 20)
test_raster(10, 20)
test_raster(20, 10)
EOF
python3 sim_raster5.py"}

