use std::fs::File;
use std::io::{BufRead, BufReader};

#[derive(Clone)]
struct Vertex { x: f32, y: f32, z: f32 }

struct Material { name: String, r: u8, g: u8, b: u8 }

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) && !args.contains(&"image".to_string()) {
        println!("Sloth 0.1\nMitchell Hynes. <mshynes@mun.ca>\nA toy for rendering 3D objects in the command line\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -x, --yaw <x>      Sets the object's static X rotation (in radians)\n    -y, --pitch <y>    Sets the object's static Y rotation (in radians)\n    -z, --roll <z>     Sets the object's static Z rotation (in radians)\n\nARGS:\n    <input filename(s)>...    Sets the input file to render\n\nSUBCOMMANDS:\n    help     Prints this message or the help of the given subcommand(s)\n    image    Generates a colorless terminal output as lines of text");
        return;
    }

    let mut w = 20;
    let mut h = 20;
    let mut bw = false;
    let mut yaw = 0.0;
    let mut pitch = 0.0;
    let mut roll = 0.0;
    let mut obj_file = String::new();

    let mut i = 1;
    while i < args.len() {
        if args[i] == "-w" { w = args[i+1].parse().unwrap(); i += 2; }
        else if args[i] == "-h" { h = args[i+1].parse().unwrap(); i += 2; }
        else if args[i] == "-x" || args[i] == "--yaw" { yaw = args[i+1].parse().unwrap(); i += 2; }
        else if args[i] == "-y" || args[i] == "--pitch" { pitch = args[i+1].parse().unwrap(); i += 2; }
        else if args[i] == "-z" || args[i] == "--roll" { roll = args[i+1].parse().unwrap(); i += 2; }
        else if args[i] == "-b" { bw = true; i += 1; }
        else if args[i] == "image" { i += 1; }
        else { obj_file = args[i].clone(); i += 1; }
    }

    // Parse OBJ
    let file = File::open(&obj_file).unwrap();
    let reader = BufReader::new(file);
    let mut vertices = Vec::new();
    let mut faces: Vec<Vec<usize>> = Vec::new();
    let mut mtl_file = String::new();
    let mut usemtl = String::new();
    let mut has_mtl = false;

    for line in reader.lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() { continue; }
        if parts[0] == "v" {
            vertices.push(Vertex { x: parts[1].parse().unwrap(), y: parts[2].parse().unwrap(), z: parts[3].parse().unwrap() });
        } else if parts[0] == "f" {
            let mut face = Vec::new();
            for p in &parts[1..] {
                let p: Vec<&str> = p.split('/').collect();
                face.push(p[0].parse::<usize>().unwrap() - 1);
            }
            faces.push(face);
        } else if parts[0] == "mtllib" {
            mtl_file = parts[1].to_string();
            has_mtl = true;
        } else if parts[0] == "usemtl" {
            usemtl = parts[1].to_string();
            has_mtl = true;
        }
    }

    if !has_mtl {
        panic!("thread 'main' panicked at src/inputs.rs:112:39:\nExpected to have materials.: OpenFileFailed");
    }

    // Apply rotations
    let cx = yaw.cos() as f32; let sx = yaw.sin() as f32;
    let cy = pitch.cos() as f32; let sy = pitch.sin() as f32;
    let cz = roll.cos() as f32; let sz = roll.sin() as f32;

    let mut min_x = f32::MAX; let mut max_x = f32::MIN;
    let mut min_y = f32::MAX; let mut max_y = f32::MIN;
    let mut min_z = f32::MAX; let mut max_z = f32::MIN;

    for v in &mut vertices {
        // Rotations: Z, Y, X? Wait, let's just do standard xyz
        let y1 = v.y * cx - v.z * sx;
        let z1 = v.y * sx + v.z * cx;
        v.y = y1; v.z = z1;

        let x2 = v.x * cy + v.z * sy;
        let z2 = -v.x * sy + v.z * cy;
        v.x = x2; v.z = z2;

        let x3 = v.x * cz - v.y * sz;
        let y3 = v.x * sz + v.y * cz;
        v.x = x3; v.y = y3;

        min_x = min_x.min(v.x); max_x = max_x.max(v.x);
        min_y = min_y.min(v.y); max_y = max_y.max(v.y);
        min_z = min_z.min(v.z); max_z = max_z.max(v.z);
    }

    let cx = (min_x + max_x) / 2.0;
    let cy = (min_y + max_y) / 2.0;
    let cz = (min_z + max_z) / 2.0;

    let extent = (max_x - min_x).max(max_y - min_y).max(max_z - min_z);
    let scale = 1.0; // Wait, extent or 2.0/extent?

    // Actually sloth might just map directly. I will tune this and test locally.
}
